"""GraphQL documents used by the US web sign-in flow.

Kept out of the example so the request sequence there stays readable. These
are the exact documents the real login page sends, whitespace and all, the
x-o-gql-query header is derived from the first two tokens, so do not reformat
them.
"""

# Warm-up query the real login page fires first.
SHIPPING_COUNTRY_LIST = "query shippingCountryList{shippingCountryList{countryDetails{code phoneCode flagAssetUrl name}errors{code}}}"

# Email lookup: tells the page which factors this account can use.
GET_LOGIN_OPTIONS = "query GetLoginOptions($input:UserOptionsInput!){getLoginOptions(input:$input){loginOptions{...LoginOptionsFragment}canUseEmailOTP phoneCollectionRequired consentCollectionRequired authCode errors{...LoginOptionsErrorFragment}}}fragment LoginOptionsFragment on LoginOptions{loginId loginIdType emailId phoneNumber{number countryCode isoCountryCode}canUsePassword canUsePhoneOTP canUseEmailOTP loginPhoneLastFour maskedPhoneNumberDetails{loginPhoneLastFour countryCode isoCountryCode}loginMaskedEmailId signInPreference loginPreference lastLoginPreference hasRemainingFactors secondFactor isPhoneConnected otherAccountsWithPhone hasPasskeyOnProfile accountDomain residencyRegion{residencyCountryCode residencyRegionCode}isIdentityMergeRequired consentRequired requiresTokenBasedPasswordSetup supportedOtpChannels}fragment LoginOptionsErrorFragment on IdentityLoginOptionsError{code message version}"

# Tempo CMS module for the 'how do you want to sign in' screen.
SIGNIN_OTP_CHOICE_MODULE = "query getSignInWithOTPChoiceModule( $pageType:String! $tempo:JSON $tenant:String! ){contentLayout(channel:\"WWW\" pageType:$pageType tenant:$tenant){modules(tempo:$tempo){name type version status schedule{start end priority expEnabled}triggers{pageType pageId zone inheritable}targeting configs{__typename...on TempoWM_GLASSWWWSignInWithOTPChoiceConfigs{logo{alt assetId assetName clickThrough{type value rawValue tag}height src title width size contentType}headerText emailAddressText phoneNumberText EmailOnlyLabelText changeEmailAddressLinkAsButton{changeEmailAddressButtonLabel ariaLabel}infoText infoTextV2 verificationText verificationTextPhone verificationTextEmail messageChargeText mobileAlertText links{link{linkText title clickThrough{type value rawValue}}}requestButton{requestButtonLabel ariaLabel}requestButtonV2{requestButtonLabel ariaLabel}inputFields{passwordInputPlaceholder passwordInputFieldLabel emptyPasswordInputFieldError}forgotPasswordLinkAsButton{forgotPasswordButtonLabel ariaLabel}checkboxes{checboxLabel checkboxValue checkboxDescription checkboxInfo{info}}signInButton{signInButtonLabel ariaLabel}privacyLinks{link{linkText title clickThrough{type value rawValue}}linkIcon{assetName height src alt assetId clickThrough{type value rawValue tag}title width size contentType uid}}}}publishedDate moduleId module_id matchedTrigger{pageType pageId zone inheritable}}layouts{id layout}}}"

# Tempo CMS module for the password screen.
SIGNIN_PASSWORD_ONLY_MODULE = "query getSignInWithPasswordOnlyModule( $pageType:String! $tempo:JSON $tenant:String! ){contentLayout(channel:\"WWW\" pageType:$pageType tenant:$tenant){modules(tempo:$tempo){name type version status schedule{start end priority expEnabled}triggers{pageType pageId zone inheritable}targeting configs{__typename...on TempoWM_GLASSWWWSignInWithPasswordOnlyConfigs{logo{alt assetId assetName clickThrough{type value rawValue tag}height src title width size contentType}headerText emailAddressText emailOnlyLabelText phoneNumberText moreInfoButton moreInfoButtonAriaLabel changeEmailAddressLinkAsButton{changeEmailAddressButtonLabel ariaLabel}inputFields{passwordInputPlaceholder passwordInputFieldLabel emptyPasswordInputFieldError}forgotPasswordLinkAsButton{forgotPasswordButtonLabel ariaLabel}checkboxes{checboxLabel checkboxValue checkboxDescription checkboxInfo{info}}signInButton{signInButtonLabel ariaLabel}}}publishedDate moduleId module_id matchedTrigger{pageType pageId zone inheritable}}layouts{id layout}}}"

# Fires the one-time code and returns the receiptId.
GENERATE_OTP = "mutation GenerateOtp($input:GenerateOTPInput!){generateOTP(input:$input){errors{...GenerateOtpErrorFragment}otpResult{...GenerateOtpResultFragment}}}fragment GenerateOtpErrorFragment on IdentityGenerateOTPError{code message}fragment GenerateOtpResultFragment on GenerateOTPResult{receiptId otpOperation otpType otherAccountsWithPhone action{alternateOption currentOption}supportedOtpChannels}"

# Tempo CMS module for the code-entry screen.
SIGNIN_OTP_MODULE = "query getSignInWithOTPModule( $pageType:String! $tenant:String! $tempo:JSON ){contentLayout(channel:\"WWW\" pageType:$pageType tenant:$tenant){modules(tempo:$tempo){name type version status schedule{start end priority expEnabled}triggers{pageType pageId zone inheritable}targeting configs{__typename...on TempoWM_GLASSWWWSignInWithOTPOnlyConfigs{logo{alt assetId assetName clickThrough{type value rawValue tag}height src title width size contentType}headerText emailAddressText phoneNumberText emailOnlyLabelText phoneNumberLabelText sixCellEmailText sixCellTotpText hideCustomerCarePopover sixPhoneNumberText changeEmailAddressLinkAsButton{changeEmailAddressButtonLabel ariaLabel}phoneNumberText inputFields{verificationCodeInputHeadingText verificationCodeInputFieldPlaceholder emptyVerificationCodeInputFieldError invalidVerificationCodeInputFieldError resendButton{resendButtonLabel ariaLabel}}signInButton{signInButtonLabel ariaLabel}verifyTotpButton{verifyTotpButtonLabel ariaLabel}useYourPasswordLinkAsButton{useYourPasswordLinkAsButtonLabel ariaLabel}checkboxes{checboxLabel checkboxValue checkboxDescription checkboxInfo{info}}}}publishedDate moduleId module_id matchedTrigger{pageType pageId zone inheritable}}layouts{id layout}}}"

# Submits the code. A wrong code returns an error, not a block.
SIGN_IN_WITH_OTP = "mutation SignInWithOTP( $input:SignInWithOTPInput! $includePhoneInfo:Boolean = false ){signInWithOTP(input:$input){auth{...SignInOtpAuthFragment}authCode{authCode cid}canUseEmailOTP phoneInfo @include(if:$includePhoneInfo){...SignInOtpPhoneInfoFragment}multiFactorInfo{ignoreFactor}errors{...SignInOtpErrorFragment}}}fragment SignInOtpAuthFragment on AuthResult{loginId cid authCode identityToken}fragment SignInOtpPhoneInfoFragment on PhoneInfo{phoneLastFour shouldCollectPhone isEmailSessionTrusted loginId isPhoneSessionTrusted isFirstSession isEmailValidated isPhoneCollMandatory}fragment SignInOtpErrorFragment on IdentitySignInWithOTPError{code message}"
